# =======================================================================
# Phase 9: upstream v4.0 bug fixes adopted by the port.
#
# VAR Toolbox 4.0 (ambropo/VAR-Toolbox@36e706a) fixed a number of defects
# in the 3.1 code this package was ported from. Where the port had
# replicated one of those defects, it now follows v4.0. This file pins the
# corrected behaviour:
#
#   - against phase9.mat, generated by gen_phase9.m from the v4.0 MATLAB
#     source on bit-identical inputs (the v3.1 fixtures' own data), for
#     every quantity v4.0 can produce through its redesigned API;
#   - by direct property tests where the fix is a control-flow change with
#     no numerical output to compare (rotation budget, bootstrap weights,
#     rejected option combinations, input guards).
#
# The v3.1 fixtures are untouched; the tests in test_phase1..8 that used to
# pin the defective values now assert the port does NOT reproduce them.
# =======================================================================

F9 = fixture("phase9")
F1 = fixture("phase1")
G2 = fixture("phase2")
H3 = fixture("phase3")
P4 = fixture("phase4")
Q5 = fixture("phase5")

@testset "Phase 9 -- fixture provenance" begin
    @test occursin("v4dot0", F9["source"])
    @test occursin("36e706a", F9["source"])
end

@testset "Phase 9 -- residual degrees of freedom" begin
    @testset "OLSmodel tprob / bint use nobs - nvar" begin
        y = F1["A"][:, 1]
        x = F1["A"][:, 2:3]
        for c in 0:2
            O = OLSmodel(y, x, c)
            p = "ols_c$(c)_"
            @golden O.tprob F9[p*"tprob"]
            @golden O.bint  F9[p*"bint"]
            @test O.nobs == Int(F9[p*"nobs"])
            @test O.nvar == Int(F9[p*"nvar"])
            # Self-consistency: the same df as sige's denominator.
            @test approxeq(O.tprob, tdis_prb(O.tstat, O.nobs - O.nvar))
        end
    end

    @testset "VARmodel tprob uses nobs - ntotcoeff" begin
        A, E = G2["A"], G2["E"]
        cfg = [(2, 1), (1, 1), (3, 1), (2, 0), (2, 2)]
        for (k, (nlag, cst)) in enumerate(cfg)
            V, _ = VARmodel(A, nlag, cst)
            p = "v$(k)_"
            @test V.ntotcoeff == Int(F9[p*"ntotcoeff"])
            for j in 1:V.nvar
                @golden V.eq[j].tprob F9[p*"eq$(j)_tprob"]
            end
        end
        ex = [(2, 2), (3, 1), (1, 3)]
        for (k, (nlag, nlx)) in enumerate(ex)
            V, _ = VARmodel(A, nlag, 1, E, nlx)
            p = "vx$(k)_"
            @test V.ntotcoeff == Int(F9[p*"ntotcoeff"])
            for j in 1:V.nvar
                @golden V.eq[j].tprob F9[p*"eq$(j)_tprob"]
            end
        end
        V, _ = VARmodel(H3["SW"], 4, 1)
        for j in 1:V.nvar
            @golden V.eq[j].tprob F9["sw_eq$(j)_tprob"]
        end
        # const = 3 (constant, trend, trend^2) is rejected by v4.0 but still
        # supported here; check the same df rule applies.
        V3, _ = VARmodel(A, 2, 3)
        for j in 1:V3.nvar
            @test approxeq(V3.eq[j].tprob,
                           tdis_prb(V3.eq[j].tstat, V3.nobs - V3.ntotcoeff))
        end
    end

    @testset "ARDLmodel tprob / bint use nobse - nvar" begin
        y1 = G2["A"][:, 1:1]
        D = ARDLmodel(y1, 2, 1)
        @golden D.tprob F9["ardl_tprob"]
        @golden D.bint  F9["ardl_bint"]
        D2 = ARDLmodel(y1, 2, 1, G2["E"], 1)
        @golden D2.tprob F9["ardl2_tprob"]
        @golden D2.bint  F9["ardl2_bint"]
    end
end

@testset "Phase 9 -- CommonSample" begin
    N = F1["N"]
    OUT, fo, lo = CommonSample(N)
    @golden OUT F9["cs_out"]
    @test fo == Int(F9["cs_fo"])
    @test lo == Int(F9["cs_lo"]) == 2
    OUT2, fo2, lo2 = CommonSample(permutedims(N), 2)
    @golden OUT2 F9["cs2_out"]
    @test (fo2, lo2) == (Int(F9["cs2_fo"]), Int(F9["cs2_lo"]))

    @testset "lo is the trailing run, interior NaNs excluded" begin
        M = [NaN 1.0; 1.0 2.0; NaN 3.0; 4.0 5.0; NaN 6.0; NaN 7.0]
        O, f, l = CommonSample(M)
        @test (f, l) == (1, 2)
        @test O == [1.0 2.0; 4.0 5.0]
        O, f, l = CommonSample(permutedims(M), 2)
        @test (f, l) == (1, 2)
    end

    @testset "empty input" begin
        @test F9["cs_empty_ok"] == 1
        O, f, l = CommonSample(zeros(0, 0))
        @test isempty(O) && (f, l) == (0, 0)
        O, f, l = CommonSample(zeros(0, 3))
        @test size(O) == (0, 3) && (f, l) == (0, 0)
    end
end

@testset "Phase 9 -- shut uses the companion recursion" begin
    SW = H3["SW"]
    V, o = VARmodel(SW, 4, 1)
    o = @set o.nsteps = 12
    o = @set o.ident = "short"
    o = @set o.shut = 2
    IR, _ = VARir(V, o)                     # default recurs = "wold"
    @golden IR F9["ir_shut2"]
    IRc, _ = VARir(V, @set o.recurs = "comp")
    @golden IRc F9["ir_shut2_comp"]
    @test approxeq(IR, IRc)                 # the two recursions now agree
    @test all(IR[:, 2, :] .== 0)            # shut variable is zero at every horizon
    # shut = 0 is unaffected: wold and comp still agree with each other and
    # with the v3.1 fixture.
    o0 = @set o.shut = 0
    IRw, _ = VARir(V, o0)
    IRk, _ = VARir(V, @set o0.recurs = "comp")
    @test approxeq(IRw, IRk; rtol = 1e-9)
    @golden IRw H3["ir_short"]
end

@testset "Phase 9 -- VARhd includes lagged exogenous regressors" begin
    SW = H3["SW"]
    EXO = F9["hd_EXOG"]
    for k in 1:4
        p = "hd$(k)_"
        nlag, nlx, cst = Int(F9[p*"nlag"]), Int(F9[p*"nlag_ex"]), Int(F9[p*"const"])
        @testset "nlag=$nlag nlag_ex=$nlx const=$cst" begin
            V, o = VARmodel(SW, nlag, cst, EXO, nlx)
            o = @set o.ident = "short"
            HD, _ = VARhd(V, o)
            @golden HD.shock    F9[p*"shock"]
            @golden HD.init     F9[p*"init"]
            @golden HD.constant F9[p*"const_c"]
            @golden HD.trend    F9[p*"trend"]
            @golden HD.exo      F9[p*"exo"]
            @golden HD.endo     F9[p*"endo"]
            # The reconstruction identity now holds to machine precision.
            recon = maximum(abs.(HD.endo[(nlag+1):end, :] .- V.Y))
            @test recon < 1e-10
            @test F9[p*"recon_err"] < 1e-10
            # ...and it would not without the lagged terms: the contribution
            # of lags kk >= 1 is not negligible.
            @test any(abs.(HD.exo[(nlag+1):end, :, :]) .> 1e-3)
        end
    end
    # nlag_ex = 0 is unchanged from v3.1 (the v3.1 fixtures have no EXOG in
    # VARhd, so pin it against the reconstruction identity instead).
    V, o = VARmodel(SW, 4, 1, EXO, 0)
    HD, _ = VARhd(V, @set o.ident = "short")
    @test maximum(abs.(HD.endo[5:end, :] .- V.Y)) < 1e-10
end

@testset "Phase 9 -- IV sample alignment (trailing and interior gaps)" begin
    ENDO = P4["gk_ENDO"]
    IV0 = P4["gk_IV"]
    V0, o = VARmodel(ENDO, 12, 1)
    o = @set o.ident = "iv"
    o = @set o.nsteps = 48
    # Same conditioning justification as the Phase 3/4/6 IV blocks:
    # cond(X'X) ~ 2.2e9 for this specification.
    IVTOL = 1e-6
    for c in ("trail", "gap", "both")
        p = "iv_$(c)_"
        IVm = F9[p*"IV"]
        @testset "$c" begin
            @test size(IVm) == size(IV0)
            V = @set V0.IV = IVm
            IR, Vo = VARir(V, o)
            # v4.0 multiplies Biv by sign(FirstStage.beta(2)) -- an
            # undocumented convention change the port does not adopt. It is
            # +1 for every case here, so this is a no-op, but divide it out
            # so the comparison is about alignment only.
            sg = F9[p*"fssign"]
            @test sg == 1.0
            @test approxeq(vec(Vo.Biv), vec(F9[p*"B1"]) .* sg; rtol = IVTOL)
            @test approxeq(IR[:, :, 1], F9[p*"IR1"] .* sg; rtol = IVTOL)
            @test approxeq(Vo.sigma_b, F9[p*"sigma_b"]; rtol = IVTOL)
            @test approxeq(Vo.FirstStage.beta, F9[p*"fsbeta"]; rtol = IVTOL)
            @test Vo.FirstStage.nobs == Int(F9[p*"nkeep"])
            # Non-vacuity: for these gap patterns the v3.1 "last n rows"
            # shortcut selects different dates than the mask.
            up = V.resid[:, 1]
            keep = .!vec(any(isnan, hcat(up, IVm[13:end, :]), dims = 2))
            n = count(keep)
            @test findall(keep) != collect((length(up)-n+1):length(up))
        end
    end
    @testset "leading-only gaps are unchanged" begin
        # The shipped Gertler-Karadi instrument is missing only at the start;
        # the mask and the shortcut select the same rows, so the Phase 6
        # fixture (v3.1) still holds. Check the row selection directly.
        up = V0.resid[:, 1]
        keep = .!vec(any(isnan, hcat(up, IV0[13:end, :]), dims = 2))
        n = count(keep)
        @test findall(keep) == collect((length(up)-n+1):length(up))
    end
end

@testset "Phase 9 -- bootstrap" begin
    ENDO = P4["gk_ENDO"]
    IV = P4["gk_IV"]
    V, o = VARmodel(ENDO, 12, 1)
    V = @set V.IV = IV
    o = @set o.ident = "iv"
    o = @set o.nsteps = 4
    o = @set o.ndraws = 2

    @testset "method = bs is rejected under ident = iv" begin
        @test_throws ArgumentError VARirband(V, @set o.method = "bs")
        # ...but not under any other scheme, and wild + iv still runs.
        o_s = @set o.ident = "short"
        o_s = @set o_s.method = "bs"
        INF, SUP, MED, BAR = VARirband(V, o_s; rng = MersenneTwister(1))
        @test size(INF) == (4, 4, 4)
        INF, SUP, MED, BAR = VARirband(V, (@set o.method = "wild"); rng = MersenneTwister(1))
        @test size(INF) == (4, 4, 4)
    end

    @testset "wild bootstrap weights with two instruments" begin
        # One Rademacher weight per observation, shared by the residual row
        # and every instrument column (v4.0). v3.1 summed the k per-column
        # signs into the residual weight.
        IV2 = hcat(IV, vcat(IV[2:end], NaN))   # a second (lagged) instrument
        V2 = @set V.IV = IV2
        ow = @set o.method = "wild"
        nobs, nlag, nvar = V2.nobs, V2.nlag, V2.nvar
        src = DrawSource(rng = MersenneTwister(7))
        y, Z = VARToolbox._artificial_data(V2, ow, src; allow_iv_wild = true)
        @test Z !== nothing
        @test size(Z) == size(IV2)
        @test isequal(Z[1:nlag, :], IV2[1:nlag, :])      # pre-sample rows untouched
        # Recover the residual weights: u_t = y_t - Ft' * [1; lags], and the
        # simulated series is built from the actual initial conditions.
        w = zeros(nobs)
        for t in 1:nobs
            jj = nlag + t
            LAG = vcat([y[jj-k, :] for k in 1:nlag]...)
            u = y[jj, :] .- vec(transpose(V2.Ft) * vcat(1.0, LAG))
            wt = u ./ V2.resid[t, :]
            @test all(isapprox.(abs.(wt), 1.0; atol = 1e-8))   # support is {-1, +1}
            @test all(isapprox.(wt, wt[1]; atol = 1e-8))       # one weight per row
            w[t] = round(wt[1])
        end
        @test any(w .== 1.0) && any(w .== -1.0)
        # Every instrument column carries the SAME per-row sign as the
        # residuals (NaN stays NaN; zero stays zero).
        Zt = Z[(nlag+1):end, :]
        IVt = IV2[(nlag+1):end, :]
        @test isequal(Zt, IVt .* w)
        # Exactly nobs uniforms are consumed, not nobs * k.
        src1 = DrawSource(uniforms = [rand(MersenneTwister(3), nobs, 1)])
        y1, _ = VARToolbox._artificial_data(V2, ow, src1; allow_iv_wild = true)
        @test size(y1, 1) == nobs + nlag
    end
end

@testset "Phase 9 -- sign restrictions" begin
    SW = H3["SW"]
    Vsw, osw = VARmodel(SW, 4, 1)
    osw = @set osw.nsteps = 8
    osw = @set osw.ident = "sign"
    nvar = Vsw.nvar

    @testset "exactly sr_rot rotations are attempted" begin
        # Square SIGN: each rotation consumes exactly one randn(nvar, nvar)
        # (through getqr). With an impossible pattern the budget is
        # exhausted, so the pool must hold sr_rot draws -- not sr_rot - 1,
        # which is all v3.1 ever used.
        impossible = ones(nvar, nvar)
        o = @set osw.sr_rot = 5
        pool5 = [randn(MersenneTwister(i), nvar, nvar) for i in 1:5]
        @test SignRestrictions(impossible, Vsw, o; src = DrawSource(normals = pool5)) === nothing
        pool4 = pool5[1:4]
        @test_throws ErrorException SignRestrictions(impossible, Vsw, o;
                                                     src = DrawSource(normals = pool4))
    end

    @testset "sr_rot = 1 works" begin
        # No restriction at all is satisfied by the first rotation; v3.1
        # returned [] regardless, so SR looped until sr_draw aborted.
        o = @set osw.sr_rot = 1
        B = SignRestrictions(zeros(nvar, nvar), Vsw, o; src = DrawSource(rng = MersenneTwister(1)))
        @test B !== nothing
        @test approxeq(B * B', Vsw.sigma; rtol = 1e-9)
        o = @set o.ndraws = 3
        o = @set o.sr_mod = 0
        out = SR(Vsw, zeros(nvar, nvar), o; rng = MersenneTwister(2))
        @test size(out.Ball, 3) == 3
    end

    @testset "posterior draws carry their own residuals (sr_mod = 1)" begin
        SIGN = H3["SIGN"]
        o = @set osw.ndraws = 4
        o = @set o.sr_mod = 1
        out = SR(Vsw, SIGN, o; rng = MersenneTwister(11))
        nlag = Vsw.nlag
        # Every accepted draw's HD reconstructs the data: this holds only if
        # the residuals used by VARhd are Y - X*Ft_draw, not the OLS ones.
        for d in 1:4
            endo_d = out.HDall[:endo][:, :, d]
            @test maximum(abs.(endo_d[(nlag+1):end, :] .- Vsw.Y)) < 1e-9
        end
        @test maximum(abs.(out.HD.endo[(nlag+1):end, :] .- Vsw.Y)) < 1e-9
        # Bands are unaffected by the residual change: they depend only on
        # the drawn (F, sigma). Replaying the same rng gives the same Ball.
        out2 = SR(Vsw, SIGN, o; rng = MersenneTwister(11))
        @test approxeq(out2.Ball, out.Ball)
        @test approxeq(out2.IRinf, out.IRinf)
    end
end

@testset "Phase 9 -- LPmodel intercept without LAGS" begin
    SW = Q5["SW"]
    ENDO5 = SW[:, 1:1]
    S5 = SW[:, 3:3]
    # v4.0 always trims max(nlag, nlag_ex) initial rows, even with no
    # controls; v3.1 (and the port) trims only when LAGS is present. Feed
    # the port the already-trimmed sample so the two regressions share it,
    # leaving the deterministic block as the only difference.
    nlag = 4
    for c in 1:2
        p = "lp_c$(c)_"
        opt = LPoption()
        opt = @set opt.nsteps = 8
        opt = @set opt.nlag = nlag
        opt = @set opt.const_ = c
        opt = @set opt.LAGS = nothing
        IR, _, _, LPout = LPmodel(ENDO5[(nlag+1):end, :], S5[(nlag+1):end, :], opt)
        @golden IR F9[p*"IR"]
        @golden LPout.h[1].beta F9[p*"h1_beta"]
        @golden LPout.h[1].x    F9[p*"h1_x"]
        @test LPout.h[1].nobs == Int(F9[p*"h1_nobs"])
        @test LPout.ntotcoeff == Int(F9[p*"ntotcoeff"])
    end
end

@testset "Phase 9 -- Stats guards" begin
    XP = F9["pc_X"]
    @test F9["movavgcent_short_errors"] == 1
    @test F9["movcorrcent_short_errors"] == 1
    @test F9["movavgcent_edge_ok"] == 1
    @test_throws ArgumentError MovAvgCent(XP[1:10, :], 5)      # nobs < 2*window+1
    @test size(MovAvgCent(XP[1:9, :], 4)) == (9, 3)            # nobs == 2*window+1 is fine
    @test_throws ArgumentError MovCorrCent(XP[1:10, :], 5, 1)
    @test size(MovCorrCent(XP[1:9, :], 4, 1)) == (9, 2)

    @testset "PairCorr with non-positive levels" begin
        @golden PairCorr(XP) F9["pc_pos"]
        # A negative or zero level: v4.0 warns, skips the log differences,
        # and the first-difference column becomes (0 - 1)/(n - 1) through
        # sum(...,'omitnan') over an all-NaN correlation matrix -- an odd
        # value, but it is what MATLAB v4.0 returns and it is pinned here.
        PCn = @test_logs (:warn, r"PairCorr") PairCorr(F9["pc_Xneg"])
        @golden PCn F9["pc_neg"]
        @test approxeq(PCn[:, 1], PairCorr(XP)[:, 1]; rtol = 1e-6) == false  # levels DO change
        PCz = @test_logs (:warn, r"PairCorr") PairCorr(F9["pc_Xzero"])
        @golden PCz F9["pc_zero"]
        @test all(PCz[:, 2] .== PCz[1, 2])                      # constant column
    end
end
